## server.py

```python
import grpc
from concurrent import futures
import user_service_pb2 as pb2
import user_service_pb2_grpc as pb2_grpc

class UserServicer(pb2_grpc.UserServiceServicer):
    def __init__(self):
        self.db = {}

    def CreateUser(self, request, context):
        import uuid
        id = str(uuid.uuid4())
        user = pb2.User(
            id=id,
            name=request.name,
            status="active",
            created_at=int(time.time())
        )
        self.db[id] = user
        return pb2.CreateUserResponse(user=user)

    def GetUser(self, request, context):
        user = self.db.get(request.id)
        if not user:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            return pb2.GetUserResponse()
        return pb2.GetUserResponse(user=user)

    def ListUsers(self, request, context):
        items = list(self.db.values())
        start = (request.page - 1) * request.page_size
        end = start + request.page_size
        return pb2.ListUsersResponse(
            users=items[start:end],
            total=len(items)
        )

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb2_grpc.add_UserServiceServicer_to_server(UserServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

